/// <summary>
/// Find method
/// </summary>
/// <param name = "_inventLocation">InventLocationId</param>
/// <param name = "_update">boolean</param>
/// <returns>METIGAWarehouses</returns>
public static METIGAWarehouses find(InventLocationId _inventLocation, boolean _update = false)
{
    METIGAWarehouses metIGAWarehouses;

    metIGAWarehouses.selectForUpdate(_update);

    if (_inventLocation)
    {
        select firstonly metIGAWarehouses
            where metIGAWarehouses.InventLocationId == _inventLocation;
    }

    return metIGAWarehouses;
}

/// <summary>
/// Exist methods
/// </summary>
/// <param name = "_inventLocation">InventLocationId</param>
/// <returns>boolean</returns>
public static boolean exist(InventLocationId _inventLocation)
{
    METIGAWarehouses metIGAWarehouses;

    return _inventLocation && (select firstonly metIGAWarehouses
                where metIGAWarehouses.InventLocationId == _inventLocation
           ).RecId != 0;
}
